viewportCameras=createViewportCameras({camera,target:controls.target,aspect:camera.aspect});viewportDisplay=createViewportDisplay({getMeshes:()=>meshes,refreshAppearance:()=>applyAppearance(),getClippingPlanes:()=>cutEnabled?[cutPlane]:[]});viewportDisplay.setMode('edges');adoptCamera(viewportCameras.setProjection('orthographic'));syncDisplayControls();updateViewNavigator();
measurementTools=createMeasurementTools({THREE:T,scene,getCamera:()=>camera,controls,canvas:renderer.domElement,container:$('#labels'),sidebar:$('#measurement-sidebar'),toolbar:$('#measurement-toolbar'),t,icon,format:fmt,formatAngle:value=>i18n.number(value,{maximumFractionDigits:2})+'°',getMeshes:()=>meshes,getSnapEdges:mesh=>viewportDisplay?.getSnapEdges(mesh),isVisible,isClipped:point=>cutEnabled&&cutPlane.distanceToPoint(point)<0,status,onChange:()=>{if(measurementTools){const active=measurementTools.getState().active;if(active!==measuring){measuring=active;if(active)stopTransform();$('#measure').classList.toggle('active',active);$('#measure').setAttribute('aria-pressed',String(active));renderer.domElement.style.cursor=active?'crosshair':''}}syncTools()},getRadius:()=>radius,fitBox:box=>{if(box.isEmpty())return;selectionActive=false;refreshSelectionBox();if(viewportCameras)adoptCamera(viewportCameras.fit(box,{padding:1.5}));controls.update()}});
window.applyViewportSettings();
syncSectionButtons();refreshTooltips();
updateInfo();
syncTools();
new ResizeObserver(entries=>{const height=entries[0]?.contentRect.height||72;document.querySelector('main').style.setProperty('--tools-height',height+'px')}).observe($('#tools'));
window.webkit?.messageHandlers.native.postMessage('ready');
